import { test, expect } from '@playwright/test';

test.describe('Coupon Code Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
  });

  test('should display error message for invalid coupon code', async ({ page }) => {
    await page.fill(getByLabel('Coupon Code'), 'INVALIDCODE');
    await page.click(getByRole('button', { name: 'Apply' }));
    const errorMessage = await page.getByText('The coupon code you entered is invalid.');
    await expect(errorMessage).toBeVisible();
  });

  test('should not display error message for valid coupon code', async ({ page }) => {
    await page.fill(getByLabel('Coupon Code'), 'VALIDCODE');
    await page.click(getByRole('button', { name: 'Apply' }));
    const errorMessage = await page.getByText('The coupon code you entered is invalid.');
    await expect(errorMessage).not.toBeVisible();
  });
});
